+func TestPtrConvReflectNewAtArray(t *testing.T) {
+	defer ptcNoPanic(t)
+	a := [2]int64{1, 2}
+	v := reflect.NewAt(reflect.TypeOf([2]ptcInt64{}), unsafe.Pointer(&a))
+	q := v.Interface().(*[2]ptcInt64)
+	if ptcTypeName(q[1]) != "ptrconv_658733.ptcInt64" || q[1] != 2 {
+		t.Errorf("element read through reflect.NewAt([2]ptcInt64, &a) = %v (%s)", q[1], ptcTypeName(q[1]))
+	}
+	if e := v.Elem().Index(1).Interface(); ptcTypeName(e) != "ptrconv_658733.ptcInt64" {
+		t.Errorf("reflect.NewAt([2]ptcInt64, &a).Elem().Index(1) has type %s", ptcTypeName(e))
+	}
+	q[0] = 5
+	if ptcTypeName(a[0]) != "int64" || a[0] != 5 {
+		t.Errorf("after a write through reflect.NewAt: a[0] = %v (%s), want 5 (int64)", a[0], ptcTypeName(a[0]))
+	}
+	if (*[2]int64)(unsafe.Pointer(q)) != &a || q != (*[2]ptcInt64)(unsafe.Pointer(&a)) {
+		t.Errorf("reflect.NewAt([2]ptcInt64, &a) lost identity")
+	}
+}
