+func TestPtrConvReflectAddresses(t *testing.T) {
+	defer ptcNoPanic(t)
+	s := ptcRawFields{n: 1}
+	f := reflect.ValueOf(&s).Elem().Field(0)
+	if unsafe.Pointer(f.UnsafeAddr()) != unsafe.Pointer(&s.n) || f.Addr().Pointer() != f.UnsafeAddr() {
+		t.Errorf("reflect address of s.n != unsafe.Pointer(&s.n)")
+	}
+	if (*ptcInt64)(unsafe.Pointer(f.UnsafeAddr())) != (*ptcInt64)(unsafe.Pointer(&s.n)) {
+		t.Errorf("pointers converted from the reflect address of s.n and from &s.n are not equal")
+	}
+	x := struct{ X int }{7}
+	if p := reflect.ValueOf(&x).Elem().Field(0).Addr().Interface().(*int); p != &x.X || ptcIntPtr(p) != ptcIntPtr(&x.X) {
+		t.Errorf("reflect address of x.X != &x.X")
+	}
+	a := [3]int{1, 2, 3}
+	e := reflect.ValueOf(&a).Elem().Index(1)
+	if p := e.Addr().Interface().(*int); p != &a[1] || ptcIntPtr(p) != ptcIntPtr(&a[1]) {
+		t.Errorf("reflect address of a[1] != &a[1]")
+	}
+	sl := []string{"a", "b"}
+	if p := reflect.ValueOf(sl).Index(1).Addr().Interface().(*string); p != &sl[1] || ptcStrPtr(p) != ptcStrPtr(&sl[1]) {
+		t.Errorf("reflect address of sl[1] != &sl[1]")
+	}
+}
