+	a := [3]int64{1, 2, 3}
+	sl := unsafe.Slice((*ptcInt64)(unsafe.Pointer(&a[0])), 3)
+	if ptcTypeName(sl[2]) != "ptrconv_658733.ptcInt64" || sl[2] != 3 {
