+package ptrconv_658733
+
+import (
+	"reflect"
+	"testing"
+	"unsafe"
+)
+
+func TestPtrConvAddressOfDereference(t *testing.T) {
+	n := 41
+	p := ptcIntPtr(&n)
+	q := &*p
+	if got := reflect.TypeOf(q).String(); got != "*int" {
+		t.Errorf("reflect.TypeOf(&*p) = %s, want *int", got)
+	}
+	if q != &n || ptcIntPtr(q) != p {
+		t.Errorf("&*p lost pointer identity")
+	}
+	var nilp ptcIntPtr
+	nilq := &*nilp
+	if nilq != nil || reflect.TypeOf(nilq).String() != "*int" {
+		t.Errorf("&*nilp = %v (%v), want nil *int", nilq, reflect.TypeOf(nilq))
+	}
+}
+
+func TestPtrConvUnsafeNestedPointerWrite(t *testing.T) {
+	n, m := 1, 2
+	p := &n
+	q := (**ptcInt)(unsafe.Pointer(&p))
+	*q = (*ptcInt)(&m)
+	if p != &m || *p != 2 {
+		t.Errorf("write through **ptcInt did not leave an *int pointing at m")
+	}
+	if unsafe.Pointer(p) != unsafe.Pointer(&m) {
+		t.Errorf("written pointer does not have m's address")
+	}
+}
+
+func TestPtrConvReflectNamedPointerElemAddr(t *testing.T) {
+	n := 9
+	p := ptcIntPtr(&n)
+	a := reflect.ValueOf(p).Elem().Addr()
+	if a.Type() != reflect.TypeOf((*int)(nil)) {
+		t.Errorf("reflect address type = %v, want *int", a.Type())
+	}
+	q, ok := a.Interface().(*int)
+	if !ok || q != &n || unsafe.Pointer(q) != unsafe.Pointer(p) {
+		t.Errorf("reflect Elem().Addr() did not return *int at p's address")
+	}
+}
